/**
 * @suppress
 */
public object FfiConverterTypeFrameSink: FfiConverter<FrameSink, Long> {
    internal val handleMap = UniffiHandleMap<FrameSink>()

    override fun lower(value: FrameSink): Long {
        if (value is FrameSinkImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): FrameSink {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return FrameSinkImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): FrameSink {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: FrameSink) = 8UL

    override fun write(value: FrameSink, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
