 */
public object FfiConverterTypeSpaceCreateListener: FfiConverter<SpaceCreateListener, Long> {
    internal val handleMap = UniffiHandleMap<SpaceCreateListener>()

    override fun lower(value: SpaceCreateListener): Long {
        if (value is SpaceCreateListenerImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): SpaceCreateListener {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return SpaceCreateListenerImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): SpaceCreateListener {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: SpaceCreateListener) = 8UL

    override fun write(value: SpaceCreateListener, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


