    @Throws(CuaException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `cloudApprove`(`provider`: kotlin.String, `deny`: kotlin.Boolean) : CloudProvider {
