/**
 * One build step. Values are literal: a Dockerfile's `$VAR`s are expanded
 * by [`BuildOptions::dockerfile`]'s parser, not here. `Run` and `Copy`
 * steps run as the `User`, in the `Workdir` and with the `Env` set before
 * them.
 */
sealed class BuildStep {

    /**
     * A shell command line (`/bin/sh -c`, or the last `Shell`).
     */
    data class Run(
        /**
         * The command line.
         */
        val `command`: kotlin.String) : BuildStep()

    {


        companion object
    }

    /**
     * A command and arguments, run without a shell.
     */
    data class RunExec(
        /**
         * Program and arguments.
         */
        val `argv`: List<kotlin.String>) : BuildStep()

    {


        companion object
    }

    /**
     * Files of the build context copied in (`COPY`; `unpack`: `ADD`).
     */
    data class Copy(
        /**
         * Paths (globs allowed) relative to the context directory.
         */
        val `sources`: List<kotlin.String>,
        /**
         * Destination in the image; relative to the current `Workdir`.
         */
        val `dest`: kotlin.String,
        /**
         * `user[:group]` that owns what lands (default root).
         */
        val `owner`: kotlin.String?,
        /**
         * A `chmod` mode applied to what lands (default: the source's).
         */
        val `mode`: kotlin.String?,
        /**
         * A local tar archive is unpacked into `dest`.
         */
        val `unpack`: kotlin.Boolean) : BuildStep()

    {


        companion object
    }

    /**
     * Environment for later steps and for commands run in the image.
     */
    data class Env(
        /**
         * Variables.
         */
        val `vars`: Map<kotlin.String, kotlin.String>) : BuildStep()

    {


        companion object
    }

    /**
     * The working directory (created when missing).
     */
    data class Workdir(
        /**
         * Directory, relative to the current one.
         */
        val `path`: kotlin.String) : BuildStep()

    {


        companion object
    }

    /**
     * The user later steps and the image's commands run as.
     */
    data class User(
        /**
         * Name or id, optionally `:group`.
         */
        val `user`: kotlin.String) : BuildStep()

    {


        companion object
    }

    /**
     * Ports the image listens on.
     */
    data class Expose(
        /**
         * Ports (`80`, `443/tcp`).
         */
        val `ports`: List<kotlin.String>) : BuildStep()

    {


        companion object
    }

    /**
     * The image's default command.
     */
    data class Cmd(
        /**
         * Program and arguments.
         */
        val `argv`: List<kotlin.String>) : BuildStep()

    {


        companion object
    }

    /**
     * The image's entrypoint.
     */
    data class Entrypoint(
        /**
         * Program and arguments.
         */
        val `argv`: List<kotlin.String>) : BuildStep()

    {


        companion object
    }

    /**
     * The shell `Run` uses.
     */
    data class Shell(
        /**
         * Program and flags (`["/bin/bash", "-c"]`).
         */
        val `argv`: List<kotlin.String>) : BuildStep()

    {


        companion object
    }

    /**
     * Image labels.
     */
    data class Label(
        /**
         * Labels.
         */
        val `labels`: Map<kotlin.String, kotlin.String>) : BuildStep()

    {


        companion object
    }

    /**
     * Volume mount points.
     */
    data class Volume(
        /**
         * Paths.
         */
        val `paths`: List<kotlin.String>) : BuildStep()

    {


        companion object
    }

    /**
     * The stop signal.
     */
    data class StopSignal(
        /**
         * Name or number.
         */
        val `signal`: kotlin.String) : BuildStep()

    {


        companion object
    }

    /**
     * The health check, as written.
     */
    data class Healthcheck(
        /**
         * The `HEALTHCHECK` arguments.
         */
        val `text`: kotlin.String) : BuildStep()

    {


        companion object
    }








    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeBuildStep : FfiConverterRustBuffer<BuildStep>{
    override fun read(buf: ByteBuffer): BuildStep {
        return when(buf.getInt()) {
            1 -> BuildStep.Run(
                FfiConverterString.read(buf),
                )
            2 -> BuildStep.RunExec(
                FfiConverterSequenceString.read(buf),
                )
            3 -> BuildStep.Copy(
                FfiConverterSequenceString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                FfiConverterOptionalString.read(buf),
                FfiConverterBoolean.read(buf),
                )
            4 -> BuildStep.Env(
                FfiConverterMapStringString.read(buf),
                )
            5 -> BuildStep.Workdir(
                FfiConverterString.read(buf),
                )
            6 -> BuildStep.User(
                FfiConverterString.read(buf),
                )
            7 -> BuildStep.Expose(
                FfiConverterSequenceString.read(buf),
                )
            8 -> BuildStep.Cmd(
                FfiConverterSequenceString.read(buf),
                )
            9 -> BuildStep.Entrypoint(
                FfiConverterSequenceString.read(buf),
                )
            10 -> BuildStep.Shell(
                FfiConverterSequenceString.read(buf),
                )
            11 -> BuildStep.Label(
                FfiConverterMapStringString.read(buf),
                )
            12 -> BuildStep.Volume(
                FfiConverterSequenceString.read(buf),
                )
            13 -> BuildStep.StopSignal(
                FfiConverterString.read(buf),
                )
            14 -> BuildStep.Healthcheck(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: BuildStep) = when(value) {
        is BuildStep.Run -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`command`)
            )
        }
        is BuildStep.RunExec -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceString.allocationSize(value.`argv`)
            )
        }
        is BuildStep.Copy -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceString.allocationSize(value.`sources`)
                + FfiConverterString.allocationSize(value.`dest`)
                + FfiConverterOptionalString.allocationSize(value.`owner`)
                + FfiConverterOptionalString.allocationSize(value.`mode`)
                + FfiConverterBoolean.allocationSize(value.`unpack`)
            )
        }
        is BuildStep.Env -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterMapStringString.allocationSize(value.`vars`)
            )
        }
        is BuildStep.Workdir -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`path`)
            )
        }
        is BuildStep.User -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`user`)
            )
        }
        is BuildStep.Expose -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceString.allocationSize(value.`ports`)
            )
        }
        is BuildStep.Cmd -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceString.allocationSize(value.`argv`)
            )
        }
        is BuildStep.Entrypoint -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceString.allocationSize(value.`argv`)
            )
        }
        is BuildStep.Shell -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceString.allocationSize(value.`argv`)
            )
        }
        is BuildStep.Label -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterMapStringString.allocationSize(value.`labels`)
            )
        }
        is BuildStep.Volume -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceString.allocationSize(value.`paths`)
            )
        }
        is BuildStep.StopSignal -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`signal`)
            )
        }
        is BuildStep.Healthcheck -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`text`)
            )
        }
    }

    override fun write(value: BuildStep, buf: ByteBuffer) {
        when(value) {
            is BuildStep.Run -> {
                buf.putInt(1)
                FfiConverterString.write(value.`command`, buf)
                Unit
            }
            is BuildStep.RunExec -> {
                buf.putInt(2)
                FfiConverterSequenceString.write(value.`argv`, buf)
                Unit
            }
            is BuildStep.Copy -> {
                buf.putInt(3)
                FfiConverterSequenceString.write(value.`sources`, buf)
                FfiConverterString.write(value.`dest`, buf)
                FfiConverterOptionalString.write(value.`owner`, buf)
                FfiConverterOptionalString.write(value.`mode`, buf)
                FfiConverterBoolean.write(value.`unpack`, buf)
                Unit
            }
            is BuildStep.Env -> {
                buf.putInt(4)
                FfiConverterMapStringString.write(value.`vars`, buf)
                Unit
            }
            is BuildStep.Workdir -> {
                buf.putInt(5)
                FfiConverterString.write(value.`path`, buf)
                Unit
            }
            is BuildStep.User -> {
                buf.putInt(6)
                FfiConverterString.write(value.`user`, buf)
                Unit
            }
            is BuildStep.Expose -> {
                buf.putInt(7)
                FfiConverterSequenceString.write(value.`ports`, buf)
                Unit
            }
            is BuildStep.Cmd -> {
                buf.putInt(8)
                FfiConverterSequenceString.write(value.`argv`, buf)
                Unit
            }
            is BuildStep.Entrypoint -> {
                buf.putInt(9)
                FfiConverterSequenceString.write(value.`argv`, buf)
                Unit
            }
            is BuildStep.Shell -> {
                buf.putInt(10)
                FfiConverterSequenceString.write(value.`argv`, buf)
                Unit
            }
            is BuildStep.Label -> {
                buf.putInt(11)
                FfiConverterMapStringString.write(value.`labels`, buf)
                Unit
            }
            is BuildStep.Volume -> {
                buf.putInt(12)
                FfiConverterSequenceString.write(value.`paths`, buf)
                Unit
            }
            is BuildStep.StopSignal -> {
                buf.putInt(13)
                FfiConverterString.write(value.`signal`, buf)
                Unit
            }
            is BuildStep.Healthcheck -> {
                buf.putInt(14)
                FfiConverterString.write(value.`text`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
 * Every error the SDK raises. Flat across the FFI: each language sees one
 * exception/error type with a case per variant and the message.
 */
sealed class CuaException(message: String): kotlin.Exception(message) {

    /**
     * Bad input.
     *
     * Fix: Check the value against the reference; the message names the
     * argument and what it accepts.
     */
        class InvalidArgument(message: String) : CuaException(message)

    /**
     * A location, kind or runtime that does not exist, or a combination of
     * them (or with the image) that does not. The message ends with the
     * valid values for that context.
     *
     * Fix: Use one of the values the message lists, or leave `kind` and
     * `runtime` unset (`auto`). `cua config list` shows the defaults in
     * effect.
     */
        class InvalidPlacement(message: String) : CuaException(message)

    /**
     * No such sandbox, process, path, forward or session.
     *
     * Fix: Check the ref, path or id. `Sandboxes.list` (`cua sb ls`) lists the
     * sandboxes this client can see.
     */
        class NotFound(message: String) : CuaException(message)

    /**
     * The provider is not configured (for example no credentials for it).
     *
     * Fix: Set the credentials the message names (for a contrib provider, its
     * environment variable or `cua auth provider set <name>`).
     */
        class ProviderNotConfigured(message: String) : CuaException(message)

    /**
     * Not supported by this provider, guest or build.
     *
     * Fix: Use a provider, image or runtime that supports the call; the
     * message names what is missing.
     */
        class Unsupported(message: String) : CuaException(message)

    /**
     * No cua-spacesd answered in the sandbox or at the URL.
     *
     * Fix: Use an image that runs cua-spacesd (the canonical Linux image does),
     * or reach the sandbox through the services it declares.
     */
        class SpacesdNotAvailable(message: String) : CuaException(message)

    /**
     * A deadline elapsed.
     *
     * Fix: Raise the timeout (for example `ready_timeout_ms`), and check that
     * the sandbox or service actually starts.
     */
        class Timeout(message: String) : CuaException(message)

    /**
     * Local runtime failure.
     *
     * Fix: Run `cua runtime doctor` (`Local.doctor`) and follow the steps it
     * prints.
     */
        class Runtime(message: String) : CuaException(message)

    /**
     * spacesd call failure.
     *
     * Fix: Read the status in the message; `SpacesdClient.capabilities` tells
     * whether this spacesd supports the call.
     */
        class Env(message: String) : CuaException(message)

    /**
     * HTTP failure talking to a sandbox service.
     *
     * Fix: Check that the service listens on its declared port and answers
     * HTTP.
     */
        class Http(message: String) : CuaException(message)

    /**
     * Missing or wrong token or ticket.
     *
     * Fix: Pass the sandbox's env token, or run `cua auth login` again.
     */
        class Unauthenticated(message: String) : CuaException(message)

    /**
     * The guest OS denied permission.
     *
     * Fix: Run the call as a guest user allowed to do it, or change the
     * permissions of the path.
     */
        class PermissionDenied(message: String) : CuaException(message)

    /**
     * Could not reach the daemon or the endpoint.
     *
     * Fix: Check the address. For a daemon client, start the daemon with `cua
     * daemon start`.
     */
        class Transport(message: String) : CuaException(message)

    /**
     * No `cua daemon` is running: nothing listens at its socket or
     * port, or its discovery file (`~/.cua/daemon.json`) was left by a
     * daemon that exited. The message says so in plain words.
     *
     * Fix: Start Cua (the Spaces app starts the daemon), or run `cua daemon
     * start`. `Cua.auto` uses the runtime in this process when no daemon
     * runs.
     */
        class DaemonNotRunning(message: String) : CuaException(message)

    /**
     * The object was closed.
     *
     * Fix: Open a new handle or session; a closed one stays closed.
     */
        class Closed(message: String) : CuaException(message)

    /**
     * The Space's spacesd reports a feature this call needs as
     * unsupported (the message names it).
     *
     * Fix: Use a Space whose spacesd supports the feature (`Space.supports`),
     * or update cua-spacesd on it.
     */
        class CapabilityMissing(message: String) : CuaException(message)

    /**
     * A host-side prerequisite (app-session providers, an operator
     * display, a local runtime) is not available.
     *
     * Fix: Install or start the prerequisite the message names on this
     * computer.
     */
        class HostCapabilityMissing(message: String) : CuaException(message)

    /**
     * The teleport consent gate refused (or the approver declined).
     *
     * Fix: Approve the manifest in the consent callback, or teleport a smaller
     * scope.
     */
        class TeleportRefused(message: String) : CuaException(message)

    /**
     * Bug or I/O failure.
     *
     * Fix: Report it with the message at https://github.com/trycua/cua/issues.
     */
        class Internal(message: String) : CuaException(message)

    /**
     * A bare sandbox name matches sandboxes in more than one location. The
     * message ends with the qualified candidates (`use one of: local:box,
     * cloud:box`); `ambiguous_sandbox_candidates` extracts them.
     *
     * Fix: Use one of the qualified refs the message lists (`local:<name>`,
     * `cloud:<name>`).
     */
        class AmbiguousSandbox(message: String) : CuaException(message)

    /**
     * A pull, build or VM create would leave less than the configured
     * minimum free disk space (`CUA_DISK_MIN_FREE`, default 5 GiB);
     * nothing was written.
     *
     * Fix: Free space with `cua cache prune`, or lower `CUA_DISK_MIN_FREE`.
     */
        class InsufficientDisk(message: String) : CuaException(message)

    /**
     * A catalog image (an `Image.*` constructor, a tier or `cua sb create
     * <word>`) that CI has not published yet. The message names the
     * reference.
     *
     * Fix: Pass the reference explicitly (`Image.from_registry("<ref>")`,
     * `cua sb create <ref>`) to use it anyway, or pick a published image
     * (`cua images ls`).
     */
        class ImageNotPublished(message: String) : CuaException(message)

    /**
     * The create was cancelled (`Spaces.cancel_create`, Ctrl-C in `cua`,
     * or its caller went away). What it made is gone; the message says
     * what was removed and what stays (finished image downloads stay
     * cached, so the next create resumes).
     *
     * Fix: Nothing to clean up. Create it again when you want it.
     */
        class Cancelled(message: String) : CuaException(message)

    /**
     * Your own cloud account (AWS, Google Cloud, Hetzner, Modal) refused or failed
     * a call Cua made for a Space there: a missing permission, a quota, a
     * region without the machine type. The message names the cloud's own
     * error.
     *
     * Fix: Fix what the message names in that account (`cua cloud test
     * <provider>` checks it without creating anything), or connect another
     * region or project.
     */
        class Cloud(message: String) : CuaException(message)

    /**
     * The machine has no room for another Space now: its VMs are at their
     * memory limit (shared snapshot memory counted once) or CPU limit, or
     * the machine itself is low on memory. Nothing was started. The
     * message says which limit, by how much, and what to do.
     *
     * Fix: Delete a Space, create it smaller (`cpus`, `memory_mb`), create
     * it on another machine (`on="auto"`), or raise the limit on this one
     * (`CUA_VM_MAX_RSS_FRACTION`, `CUA_VM_VCPU_OVERCOMMIT`).
     */
        class HostCapacity(message: String) : CuaException(message)


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CuaException> {
        override fun lift(error_buf: RustBuffer.ByValue): CuaException = FfiConverterTypeCuaError.lift(error_buf)
    }
}

