        /**
         * User name.
         */
        val `username`: kotlin.String,
        /**
         * Password or token.
         */
        val `password`: kotlin.String,
        /**
         * Registry host; `None` means the image's.
         */
        val `registry`: kotlin.String?) : RegistrySecret()

    {


        companion object
    }

    /**
     * Read from environment variables of this process at create time.
     */
    data class FromEnv(
        /**
         * Variable holding the user name.
         */
        val `usernameVar`: kotlin.String,
        /**
         * Variable holding the password or token.
         */
        val `passwordVar`: kotlin.String,
        /**
         * Registry host; `None` means the image's.
         */
        val `registry`: kotlin.String?) : RegistrySecret()

    {


        companion object
    }

    /**
     * A private Amazon ECR image: a login token from the AWS CLI
     * (`aws ecr get-login-password`) with the caller's AWS credentials.
     */
    data class AwsEcr(
        /**
         * Region; `None` takes it from the image's ECR host.
         */
        val `region`: kotlin.String?) : RegistrySecret()

    {


        companion object
    }








    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeRegistrySecret : FfiConverterRustBuffer<RegistrySecret>{
    override fun read(buf: ByteBuffer): RegistrySecret {
        return when(buf.getInt()) {
            1 -> RegistrySecret.Basic(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            2 -> RegistrySecret.FromEnv(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            3 -> RegistrySecret.AwsEcr(
                FfiConverterOptionalString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: RegistrySecret) = when(value) {
        is RegistrySecret.Basic -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`username`)
                + FfiConverterString.allocationSize(value.`password`)
                + FfiConverterOptionalString.allocationSize(value.`registry`)
            )
        }
        is RegistrySecret.FromEnv -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`usernameVar`)
                + FfiConverterString.allocationSize(value.`passwordVar`)
                + FfiConverterOptionalString.allocationSize(value.`registry`)
            )
        }
        is RegistrySecret.AwsEcr -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalString.allocationSize(value.`region`)
            )
        }
    }

    override fun write(value: RegistrySecret, buf: ByteBuffer) {
        when(value) {
            is RegistrySecret.Basic -> {
                buf.putInt(1)
                FfiConverterString.write(value.`username`, buf)
                FfiConverterString.write(value.`password`, buf)
                FfiConverterOptionalString.write(value.`registry`, buf)
                Unit
            }
            is RegistrySecret.FromEnv -> {
                buf.putInt(2)
                FfiConverterString.write(value.`usernameVar`, buf)
                FfiConverterString.write(value.`passwordVar`, buf)
                FfiConverterOptionalString.write(value.`registry`, buf)
                Unit
            }
            is RegistrySecret.AwsEcr -> {
                buf.putInt(3)
                FfiConverterOptionalString.write(value.`region`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





