 */
public object FfiConverterMapStringUShort: FfiConverterRustBuffer<Map<kotlin.String, kotlin.UShort>> {
    override fun read(buf: ByteBuffer): Map<kotlin.String, kotlin.UShort> {
        val len = buf.getInt()
        return buildMap<kotlin.String, kotlin.UShort>(len) {
            repeat(len) {
                val k = FfiConverterString.read(buf)
                val v = FfiConverterUShort.read(buf)
                this[k] = v
            }
        }
    }

    override fun allocationSize(value: Map<kotlin.String, kotlin.UShort>): ULong {
        val spaceForMapSize = 4UL
        val spaceForChildren = value.map { (k, v) ->
            FfiConverterString.allocationSize(k) +
            FfiConverterUShort.allocationSize(v)
        }.sum()
        return spaceForMapSize + spaceForChildren
    }

    override fun write(value: Map<kotlin.String, kotlin.UShort>, buf: ByteBuffer) {
        buf.putInt(value.size)
        // The parens on `(k, v)` here ensure we're calling the right method,
        // which is important for compatibility with older android devices.
        // Ref https://blog.danlew.net/2017/03/16/kotlin-puzzler-whose-line-is-it-anyways/
        value.forEach { (k, v) ->
            FfiConverterString.write(k, buf)
            FfiConverterUShort.write(v, buf)
        }
    }
}




